  P: [[[0, 0], [0, 6], [3, 6], [4, 5], [4, 4], [3, 3], [0, 3]]], R: [[[0, 0], [0, 6], [3, 6], [4, 5], [4, 4], [3, 3], [0, 3]], [[2, 3], [4, 0]]],
  S: [[[4, 5], [3, 6], [1, 6], [0, 5], [0, 4], [1, 3], [3, 3], [4, 2], [4, 1], [3, 0], [1, 0], [0, 1]]], T: [[[0, 6], [4, 6]], [[2, 6], [2, 0]]], V: [[[0, 6], [2, 0], [4, 6]]], Y: [[[0, 6], [2, 3], [4, 6]], [[2, 3], [2, 0]]]
