    for (let v = 45; v < 540; v += 45) { P.line([I(v, 150, .3), I(v, 540, .3)], 0.35); P.line([I(0, 150 + v * 0.72, .3), I(540, 150 + v * 0.72, .3)], 0.35); }
    /* le parvis : mur bas et portique */
    heAshlar(P, 0, 0, 0, 24, 150, 70, 'y3r2b2k2', { c: 18, bl: 30 });
    /* le Temple, sa façade ornée de couronnes et d'écussons d'or (1 Maccabées 4, 57) */
    heTemple(P, 140, 20, 0, 250, 120, 186, { veil: 1, shields: 1, cren: 1, tn: 'y2r1b1' });
    P.box(222, 156, 0, 86, 14, 6, 'y2r1b1', 0.6);
    heAshlar(P, 0, 150, 0, 24, 390, 70, 'y3r2b2k2', { c: 18, bl: 30 });
    for (let i = 0; i < 4; i++) heCol(P, 38, 200 + i * 96, 0, 96, 7, 'y2r1b1');
    /* l'autel neuf, de pierres non taillées */
