    for (let z = 24; z < 144; z += 24) P.line([I(-100, 210, z), I(0, 210, z)], 0.5);
    P.shape([I(-100, 0, 144), I(0, 0, 144), I(0, 210, 144), I(-100, 210, 144)], 'y3r1k1', 1);
    const T = heTemple(P, -92, 44, 144, 64, 110, 126, { fx: 1, steps: false, cren: 1, vine: 1, veil: 1 });
    heScaffold(P, T.F, 110, 126, 3);
    /* le mur : assises de grands blocs à bossage, plus basses vers l'avant où l'on bâtit encore */
    { const rows = [540, 540, 470, 380, 300, 210]; for (let r = 0; r < rows.length; r++) { let y = r % 2 ? -26 : 0, i = 0; while (y < rows[r]) { const bw = 52 + ((i * 7 + r * 13) % 4) * 9, y0 = Math.max(0, y), y1 = Math.min(rows[r], y + bw); if (y1 - y0 > 8) heBlock(P, 0, y0, r * 24, 46, y1 - y0, 24, (i + r) % 3 ? 'y2r1k1' : 'y3r1k1', 0.8); y += bw; i++; } } }
    /* la route des carrières */
    P.fill([I(210, 384, .3), I(540, 384, .3), I(540, 450, .3), I(210, 450, .3)], 'y3r2', {});
    /* la chèvre de levage et son treuil */
    for (const b of [250, 312]) heBeam(P, I(104, b, 0), I(72, 281, 218), 6);
    heBeam(P, I(99, 257, 70), I(99, 305, 70), 4); heBeam(P, I(88, 266, 130), I(88, 296, 130), 4);
    P.line([I(72, 281, 218), I(168, 284, 26)], 0.9);
    P.box(156, 270, 0, 8, 28, 30, 'r4y5k4', 0.7); P.cyl(172, 284, 18, 8, 10, 'r4y6k2', 0.7, 10);
    /* blocs en attente, éclats */
    heBlock(P, 246, 146, 0, 62, 32, 24); heBlock(P, 318, 296, 0, 58, 32, 24, 'y3r1k1');
    heBlock(P, 236, 60, 0, 60, 30, 24, 'y3r1k1'); heBlock(P, 242, 64, 24, 50, 26, 22);
    Lib.stones(P, 16, 'y2r1k2', [230, 170, 190, 120]);
    /* un bloc sur ses rondins */
    for (let i = 0; i < 4; i++) P.cyl(150 + i * 18, 486, 0, 5, 5, 'r4y5k3', 0.5, 8);
    heBlock(P, 140, 468, 6, 70, 34, 24);
    /* l'estrade du roi et son dais */
